// AES Encryption/Decryption Test
import {AESEncryption} from "@devopsthink/react-security-util";

// Test: Encrypt and Decrypt a Simple Value
const enc_str = AESEncryption.encrypt("1");
console.log("enc_str", enc_str);
const dec_str = AESEncryption.decrypt(enc_str);
console.log("dec_str", dec_str);

// Test: Decrypt a Pre-Encrypted Payload
const enc = ""
console.log(AESEncryption.decrypt(enc));